371: // --- 7. INTERACTION CONTROLS (360 Orbit, Drag, Zoom, Hover) ---
372: let isDragging = false;
373: let previousMousePosition = { x: 0, y: 0 };
374: let targetRotationY = 0;
375: let targetRotationX = 0;
376: let currentRotationY = 0;
377: let currentRotationX = 0;
378: let targetZoom = 6.5;
379: let currentZoom = 6.5;
380: 
381: function onMouseDown(e) {
382:   isDragging = true;
383:   previousMousePosition = { x: e.clientX, y: e.clientY };
384: }
385: 
386: function onMouseMove(e) {
387:   if (isDragging) {
388:     const deltaX = e.clientX - previousMousePosition.x;
389:     const deltaY = e.clientY - previousMousePosition.y;
390: 
391:     targetRotationY += deltaX * 0.007;
392:     targetRotationX = Math.max(-0.45, Math.min(0.45, targetRotationX + deltaY * 0.005));
393: 
394:     previousMousePosition = { x: e.clientX, y: e.clientY };
395:   }
396: }
397: 
398: function onMouseUp() {
399:   isDragging = false;
400: }
401: 
402: function onWheel(e) {
403:   targetZoom += e.deltaY * 0.003;
404:   targetZoom = Math.max(4.0, Math.min(9.5, targetZoom));
405: }
406: 
407: // Touch controls for mobile/tablet 360 rotation
408: function onTouchStart(e) {
409:   if (e.touches.length === 1) {
410:     isDragging = true;
411:     previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
412:   }
413: }
414: 
415: function onTouchMove(e) {
416:   if (isDragging && e.touches.length === 1) {
417:     const deltaX = e.touches[0].clientX - previousMousePosition.x;
418:     const deltaY = e.touches[0].clientY - previousMousePosition.y;
419:     targetRotationY += deltaX * 0.008;
420:     targetRotationX = Math.max(-0.4, Math.min(0.4, targetRotationX + deltaY * 0.006));
421:     previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
422:   }
423: }
424: 
425: function onTouchEnd() {
426:   isDragging = false;
427: }
428: 
429: window.addEventListener('mousedown', onMouseDown);
430: window.addEventListener('mousemove', onMouseMove);
431: window.addEventListener('mouseup', onMouseUp);
432: window.addEventListener('wheel', onWheel, { passive: true });
433: window.addEventListener('touchstart', onTouchStart, { passive: true });
434: window.addEventListener('touchmove', onTouchMove, { passive: true });
435: window.addEventListener('touchend', onTouchEnd);
436: 
437: // Interactive Click trigger: Raycaster to bounce dog or cat when clicked
438: const raycaster = new THREE.Raycaster();
439: const mouseVec = new THREE.Vector2();
440: 
441: window.addEventListener('click', (e) => {
442:   const rect = renderer.domElement.getBoundingClientRect();
443:   mouseVec.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
444:   mouseVec.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
445:   raycaster.setFromCamera(mouseVec, camera);
446: 
447:   const intersects = raycaster.intersectObjects([dogHead, catHead, stethObj, heartGroup], true);
448:   if (intersects.length > 0) {
449:     // trigger small bounce pulse
450:     dogGroup.position.y = -0.3;
451:     catGroup.position.y = -0.4;
452:     setTimeout(() => {
453:       dogGroup.position.y = -0.6;
454:       catGroup.position.y = -0.65;
455:     }, 250);
456:   }
457: });
458: 
459: // Window resize listener
460: function handleResize() {
461:   const w = container.clientWidth || window.innerWidth;
462:   const h = container.clientHeight || window.innerHeight;
463:   camera.aspect = w / h;
464:   camera.updateProjectionMatrix();
465:   renderer.setSize(w, h);
466: }
467: window.addEventListener('resize', handleResize);
468: 
469: // Animation Loop
470: let clock = new THREE.Clock();
471: 
472: function animate() {
473:   requestAnimationFrame(animate);
474:   const elapsed = clock.getElapsedTime();
475: 
476:   // Smooth rotation damping
477:   currentRotationY += (targetRotationY - currentRotationY) * 0.08;
478:   currentRotationX += (targetRotationX - currentRotationX) * 0.08;
479:   worldGroup.rotation.y = currentRotationY + (isDragging ? 0 : Math.sin(elapsed * 0.3) * 0.15);
480:   worldGroup.rotation.x = currentRotationX;
481: 
482:   // Smooth zoom damping
483:   currentZoom += (targetZoom - currentZoom) * 0.08;
484:   camera.position.z = currentZoom;
485: 
486:   // Gentle character breathing & idling animations
487:   dogHeadGroup.rotation.z = Math.sin(elapsed * 2.0) * 0.06;
488:   dogHeadGroup.rotation.y = Math.cos(elapsed * 1.5) * 0.08;
489:   tail.rotation.z = Math.sin(elapsed * 8.0) * 0.35; // Wagging tail
490: 
491:   catHeadGroup.rotation.x = Math.sin(elapsed * 1.2) * 0.05;
492:   catTail.rotation.z = 0.5 + Math.sin(elapsed * 2.5) * 0.18;
493: 
494:   // Float items
495:   floatingItems.forEach(item => {
496:     item.mesh.position.y = item.basePos.y + Math.sin(elapsed * item.speed) * item.amp;
497:     item.mesh.rotation.y += item.rotSpeed;
498:     item.mesh.rotation.x += item.rotSpeed * 0.5;
499:   });
500: 
501:   // Rotate particles gently
502:   particles.rotation.y = elapsed * 0.03;
503: 
504:   renderer.render(scene, camera);
505: }
506: 
507: animate();
508: 
509: })();
