    armR.rotation.x = -0.4;
    vetGroup.add(armL, armR);
    worldGroup.add(vetGroup);

    const floatingItems = [];
    function createMedicalCross(size, colorMat) {
      const group = new THREE.Group();
      const vBar = new THREE.Mesh(new THREE.BoxGeometry(size * 0.35, size, size * 0.3), colorMat);
      const hBar = new THREE.Mesh(new THREE.BoxGeometry(size, size * 0.35, size * 0.3), colorMat);
      group.add(vBar, hBar);
      return group;
    }
    const cross1 = createMedicalCross(0.42, matEmeraldGlow);
    cross1.position.set(-2.2, 1.2, 0.5);
    worldGroup.add(cross1);
    floatingItems.push({ mesh: cross1, basePos: cross1.position.clone(), speed: 1.8, amp: 0.18, rotSpeed: 0.02 });

    const cross2 = createMedicalCross(0.3, matCyanGlow);
    cross2.position.set(2.4, 1.6, -0.2);
    worldGroup.add(cross2);
    floatingItems.push({ mesh: cross2, basePos: cross2.position.clone(), speed: 2.2, amp: 0.15, rotSpeed: -0.025 });

    const heartGroup = new THREE.Group();
    const hSphere1 = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 12), matRoseGlow);
    hSphere1.position.set(-0.12, 0.08, 0);
    const hSphere2 = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 12), matRoseGlow);
    hSphere2.position.set(0.12, 0.08, 0);
    const hCone = new THREE.Mesh(new THREE.ConeGeometry(0.24, 0.35, 12), matRoseGlow);
    hCone.rotation.z = Math.PI;
    hCone.position.set(0, -0.12, 0);
    heartGroup.add(hSphere1, hSphere2, hCone);
    heartGroup.position.set(-1.8, 2.0, -0.8);
    worldGroup.add(heartGroup);
    floatingItems.push({ mesh: heartGroup, basePos: heartGroup.position.clone(), speed: 2.5, amp: 0.22, rotSpeed: 0.015 });

    const stethObj = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.22, 0.08, 20), matCyanGlow);
    stethObj.rotation.x = 0.5;
    stethObj.position.set(2.0, 0.3, 0.8);
    worldGroup.add(stethObj);
    floatingItems.push({ mesh: stethObj, basePos: stethObj.position.clone(), speed: 1.4, amp: 0.14, rotSpeed: 0.03 });

    const pillGroup = new THREE.Group();
    const pillGeo = new THREE.CapsuleGeometry ? new THREE.CapsuleGeometry(0.1, 0.28, 8, 16) : new THREE.CylinderGeometry(0.1, 0.1, 0.28, 12);
    const pill = new THREE.Mesh(pillGeo, matEmeraldGlow);
    pill.rotation.z = 0.8;
    pillGroup.add(pill);
    pillGroup.position.set(1.9, 2.2, 0.2);
    worldGroup.add(pillGroup);
    floatingItems.push({ mesh: pillGroup, basePos: pillGroup.position.clone(), speed: 1.9, amp: 0.2, rotSpeed: 0.02 });

    const podiumGeo = new THREE.CylinderGeometry(2.4, 2.7, 0.18, 36);
    const podium = new THREE.Mesh(podiumGeo, matGlassPod);
    podium.position.y = -0.75;
    podium.receiveShadow = true;
    worldGroup.add(podium);

    const ringGlowGeo = new THREE.TorusGeometry(2.42, 0.035, 12, 48);
    const ringGlow = new THREE.Mesh(ringGlowGeo, matCyanGlow);
    ringGlow.rotation.x = Math.PI / 2;
    ringGlow.position.y = -0.66;
    worldGroup.add(ringGlow);

    const particleCount = 85;
    const particleGeo = new THREE.BufferGeometry();
    const positions = new Float32Array(particleCount * 3);
    const scales = new Float32Array(particleCount);
    for (let i = 0; i < particleCount; i++) {
      positions[i * 3] = (Math.random() - 0.5) * 10;
      positions[i * 3 + 1] = (Math.random() - 0.2) * 6;
      positions[i * 3 + 2] = (Math.random() - 0.5) * 8;
      scales[i] = Math.random() * 0.06 + 0.02;
    }
    particleGeo.setAttribute('position', new THREE.BufferAttribute(positions, 3));
    const particleMat = new THREE.PointsMaterial({
      color: 0x38bdf8,
      size: 0.08,
      transparent: true,
      opacity: 0.75,
      blending: THREE.AdditiveBlending
    });
    const particles = new THREE.Points(particleGeo, particleMat);
    scene.add(particles);

    let isDragging = false;
    let previousMousePosition = { x: 0, y: 0 };
    let targetRotationY = 0;
    let targetRotationX = 0;
    let currentRotationY = 0;
    let currentRotationX = 0;
    let targetZoom = 6.5;
    let currentZoom = 6.5;

    function onMouseDown(e) {
      isDragging = true;
      previousMousePosition = { x: e.clientX, y: e.clientY };
    }
    function onMouseMove(e) {
      if (isDragging) {
        const deltaX = e.clientX - previousMousePosition.x;
        const deltaY = e.clientY - previousMousePosition.y;
        targetRotationY += deltaX * 0.007;
        targetRotationX = Math.max(-0.45, Math.min(0.45, targetRotationX + deltaY * 0.005));
        previousMousePosition = { x: e.clientX, y: e.clientY };
      }
    }
    function onMouseUp() {
      isDragging = false;
    }
    function onWheel(e) {
      targetZoom += e.deltaY * 0.003;
      targetZoom = Math.max(4.0, Math.min(9.5, targetZoom));
    }
    function onTouchStart(e) {
      if (e.touches.length === 1) {
        isDragging = true;
        previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      }
    }
    function onTouchMove(e) {
      if (isDragging && e.touches.length === 1) {
        const deltaX = e.touches[0].clientX - previousMousePosition.x;
        const deltaY = e.touches[0].clientY - previousMousePosition.y;
        targetRotationY += deltaX * 0.008;
        targetRotationX = Math.max(-0.4, Math.min(0.4, targetRotationX + deltaY * 0.006));
        previousMousePosition = { x: e.touches[0].clientX, y: e.touches[0].clientY };
      }
    }
    function onTouchEnd() {
      isDragging = false;
    }

    window.addEventListener('mousedown', onMouseDown);
    window.addEventListener('mousemove', onMouseMove);
    window.addEventListener('mouseup', onMouseUp);
    window.addEventListener('wheel', onWheel, { passive: true });
    window.addEventListener('touchstart', onTouchStart, { passive: true });
    window.addEventListener('touchmove', onTouchMove, { passive: true });
    window.addEventListener('touchend', onTouchEnd);

    const raycaster = new THREE.Raycaster();
    const mouseVec = new THREE.Vector2();

    const onClick = (e) => {
      const rect = renderer.domElement.getBoundingClientRect();
      mouseVec.x = ((e.clientX - rect.left) / rect.width) * 2 - 1;
      mouseVec.y = -((e.clientY - rect.top) / rect.height) * 2 + 1;
      raycaster.setFromCamera(mouseVec, camera);

      const intersects = raycaster.intersectObjects([dogHead, catHead, stethObj, heartGroup], true);
      if (intersects.length > 0) {
        dogGroup.position.y = -0.3;
        catGroup.position.y = -0.4;
        setTimeout(() => {
          dogGroup.position.y = -0.6;
          catGroup.position.y = -0.65;
        }, 250);
      }
    };
    window.addEventListener('click', onClick);

    function handleResize() {
      const w = container.clientWidth;
      const h = container.clientHeight;
      camera.aspect = w / h;
      camera.updateProjectionMatrix();
      renderer.setSize(w, h);
    }
    window.addEventListener('resize', handleResize);

    const clock = new THREE.Clock();
    let animationId;

    function animate() {
      animationId = requestAnimationFrame(animate);
      const elapsed = clock.getElapsedTime();

      currentRotationY += (targetRotationY - currentRotationY) * 0.08;
      currentRotationX += (targetRotationX - currentRotationX) * 0.08;
      worldGroup.rotation.y = currentRotationY + (isDragging ? 0 : Math.sin(elapsed * 0.3) * 0.15);
      worldGroup.rotation.x = currentRotationX;

      currentZoom += (targetZoom - currentZoom) * 0.08;
      camera.position.z = currentZoom;

      dogHeadGroup.rotation.z = Math.sin(elapsed * 2.0) * 0.06;
      dogHeadGroup.rotation.y = Math.cos(elapsed * 1.5) * 0.08;
      tail.rotation.z = Math.sin(elapsed * 8.0) * 0.35;

      catHeadGroup.rotation.x = Math.sin(elapsed * 1.2) * 0.05;
      catTail.rotation.z = 0.5 + Math.sin(elapsed * 2.5) * 0.18;

      floatingItems.forEach(item => {
        item.mesh.position.y = item.basePos.y + Math.sin(elapsed * item.speed) * item.amp;
        item.mesh.rotation.y += item.rotSpeed;
        item.mesh.rotation.x += item.rotSpeed * 0.5;
      });

      particles.rotation.y = elapsed * 0.03;

      renderer.render(scene, camera);
    }

    animate();

    return () => {
      cancelAnimationFrame(animationId);
      window.removeEventListener('mousedown', onMouseDown);
      window.removeEventListener('mousemove', onMouseMove);
      window.removeEventListener('mouseup', onMouseUp);
      window.removeEventListener('wheel', onWheel);
      window.removeEventListener('touchstart', onTouchStart);
      window.removeEventListener('touchmove', onTouchMove);
      window.removeEventListener('touchend', onTouchEnd);
      window.removeEventListener('click', onClick);
      window.removeEventListener('resize', handleResize);
      container.removeChild(renderer.domElement);
    };
  }, []);

  return <div ref={mountRef} className="absolute inset-0 w-full h-full bg-transparent z-0" />;
}

import React from 'react';
import Header from './components/Header';
import HeroSection from './components/HeroSection';
import HowItWorksSection from './components/HowItWorksSection';
import TelemetrySection from './components/TelemetrySection';

function App() {
  return (
    <div className="bg-background font-body-md text-on-surface antialiased min-h-screen">
      <Header />
      <main className="w-full pt-20 bg-background min-h-screen">
        <div className="flex flex-col w-full">
          <HeroSection />
          <HowItWorksSection />
          <TelemetrySection />
        </div>
      </main>
    </div>
  );
}

export default App;
